style.css:
@-moz-document url-prefix("https://fatality.win/") {
/* === FORCE Purple/Pink Backgrounds & Text Everywhere === */
/* Tabs container */
.tabs {
    background: transparent !important;
    border-bottom: 2px solid #ff33cc !important;
}

/* Each tab */
.tabs-tab {
    background: linear-gradient(135deg, #bb33ff, #ff33cc) !important;
    color: #fff !important;
    border: none !important;
    box-shadow: 0 0 15px #ff33cc !important;
    transition: background 0.4s ease !important;
}

/* Active and hover tab states */
.tabs-tab.is-active,
.tabs-tab:hover {
    background: linear-gradient(135deg, #ff33cc, #bb33ff) !important;
    box-shadow: 0 0 30px #ff66ff !important;
    color: #fff !important;
}

/* Tab text */
.tabs-tab > a {
    color: #fff !important;
    text-shadow: 0 0 10px #ff33cc !important;
}

/* Navigation Bar */
.p-nav {
    background: linear-gradient(90deg, #5e008c, #bb33ff) !important;
    box-shadow: 0 0 20px #ff33cc inset !important;
    border-bottom: 3px solid #ff33cc !important;
}

/* Navigation links */
.p-nav a {
    color: #ffccff !important;
    text-shadow: 0 0 8px #ff33cc !important;
    font-weight: 600 !important;
}

.p-nav a:hover {
    color: #fff !important;
    text-shadow: 0 0 15px #ff66ff !important;
}

/* Shout Box container */
.p-shoutbox,
.p-shoutbox .message-cell {
    background: linear-gradient(135deg, #3d0066, #720099) !important;
    border-radius: 15px !important;
    box-shadow: 0 0 12px #bb33ff inset !important;
    color: #ffe6ff !important;
    border: none !important;
}

/* Shout Box text inputs */
.p-shoutbox textarea,
.p-shoutbox input {
    background: #32004d !important;
    color: #ffccff !important;
    border: 1px solid #bb33ff !important;
    box-shadow: 0 0 10px #ff33cc inset !important;
}

/* Shout Box buttons */
.p-shoutbox button {
    background: linear-gradient(135deg, #bb33ff, #ff33cc) !important;
    color: white !important;
    border-radius: 20px !important;
    border: none !important;
    box-shadow: 0 0 15px #ff33cc !important;
    transition: background 0.4s ease !important;
}

.p-shoutbox button:hover {
    background: linear-gradient(135deg, #ff33cc, #bb33ff) !important;
    box-shadow: 0 0 30px #ff66ff !important;
}

/* Latest Posts and Latest Profile Posts blocks */
.block--latestPosts,
.block--latestProfilePosts {
    background: linear-gradient(135deg, #3d0066, #720099) !important;
    border-radius: 15px !important;
    box-shadow: 0 0 20px #bb33ff inset !important;
    color: #ffe6ff !important;
    border: none !important;
    padding: 15px !important;
}

/* Headers inside latest posts */
.block--latestPosts .block-header,
.block--latestProfilePosts .block-header {
    color: #ff99ff !important;
    text-shadow: 0 0 15px #bb33ff !important;
    border-bottom: 2px solid #ff33cc !important;
    padding-bottom: 5px !important;
}

/* Posts inside those blocks */
.block--latestPosts .message-cell,
.block--latestProfilePosts .message-cell {
    background: linear-gradient(135deg, #4a0080, #8900c0) !important;
    border-radius: 10px !important;
    margin-bottom: 10px !important;
    box-shadow: 0 0 12px #bb33ff inset !important;
    color: #ffe6ff !important;
}

/* Scrollbar override inside blocks (optional) */
.block--latestPosts::-webkit-scrollbar,
.block--latestProfilePosts::-webkit-scrollbar {
    width: 10px !important;
}

.block--latestPosts::-webkit-scrollbar-thumb,
.block--latestProfilePosts::-webkit-scrollbar-thumb {
    background: #bb33ff !important;
    border-radius: 5px !important;
}

/* Ensure no black backgrounds anywhere */
* {
    background-color: unset !important;
}

/* Force links in all blocks */
.block--latestPosts a,
.block--latestProfilePosts a {
    color: #ff66ff !important;
    text-decoration: none !important;
    text-shadow: 0 0 8px #ff33cc !important;
}

.block--latestPosts a:hover,
.block--latestProfilePosts a:hover {
    color: #fff !important;
    text-shadow: 0 0 15px #ff66ff !important;
}

