/* Center the logo container */
.ft-logo {
    margin: 0 auto;
    display: block;
    /* make it a block element so margin auto works */
    text-align: center;
}

/* If .ft-logo is inside a flex or grid parent, force centering */
.ft-logo {
    display: flex !important;
    justify-content: center !important;
