    color: #fff !important;
    text-shadow: 0 0 10px #ff33cc !important;
}

/* === Fatality.win Iconic Purple/Pink Theme === */
/* --- Logo Container and Text --- */
.ft-logo {
    position: relative;
    background: linear-gradient(135deg, #bb33ff, #bb33ff);
    padding: 10px 30px;
    border-radius: 25px;
    box-shadow: 0 0 40px #bb33ff, 0 0 70px #bb33ff;  
    z-index: 10;
    display: inline-block;
}

/* Override inline styles if any */
.ft-logo[style] {
    background: none !important;
}

/* Logo Text */
.ft-logo .ft-text {
    font-family: 'Arial Black', Arial, sans-serif;
    font-weight: 90;
    font-size: 36px;
    color: #bb33ff;
    position: relative;
    z-index: 20;
    text-shadow: 0 0 10px #ff33cc,
    0 0 25px #bb33ff,
    0 0 35px #bb33ff;
    user-select: none;
    text-transform: uppercase;
    letter-spacing: 4px;
}

/* Glowing blurred background behind logo container */
.ft-logo::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 270px;
    height: 90px;
    background: radial-gradient(circle at center, #bb33ff 0%, #bb33ff 70%, transparent 90%);
    filter: blur(28px);
    transform: translate(-50%, -50%);
    z-index: 5;
    border-radius: 30px;
    animation: pulseGlow 3s infinite ease-in-out;
    pointer-events: none;
}

/* Glow animation */
@keyframes pulseGlow {
    0%,
    100% {
        filter: blur(25px);
        opacity: 0.8;
    }
    50% {
        filter: blur(30px);
        opacity: 1;
    }
}

/* --- Footer Styling --- */
.p-footer {
    background: linear-gradient(90deg, #5e008c, #bb33ff) !important;
    border-top: 3px solid #ff33cc !important;
    box-shadow: 0 0 20px #ff33cc inset;
    color: #ffccff !important;
    text-align: center;
    padding: 15px 0;
    font-weight: 600;
    text-shadow: 0 0 10px #ff33cc;
    font-size: 14px;
}

/* Footer links */
.p-footer a {
    color: #ff99ff !important;
    text-shadow: 0 0 8px #ff33cc;
}

.p-footer a:hover {
    color: #fff !important;
    text-shadow: 0 0 15px #ff66ff;
}

/* --- General Forum Theming for Fatality Style --- */
/* Background for main container */
.p-body,
.p-body-content {
    background: linear-gradient(135deg, #2b0044, #520066);
    color: #ff99ff;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

/* Links in forum */
a {
    color: #ff66ff;
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: #ff33cc;
    text-shadow: 0 0 8px #ff33cc;
}

/* Buttons and tabs */
.button,
.tabs-tab {
    background: linear-gradient(135deg, #bb33ff, #ff33cc);
    border: none;
    color: white;
    padding: 8px 20px;
    border-radius: 20px;
    box-shadow: 0 0 15px #ff33cc;
    transition: background 0.4s ease;
}

.button:hover,
.tabs-tab:hover {
    background: linear-gradient(135deg, #ff33cc, #bb33ff);
    box-shadow: 0 0 30px #ff66ff;
}

/* Forum headers */
.block-header,
.block-header-title {
    color: #ff99ff;
    text-shadow: 0 0 15px #bb33ff;
    border-bottom: 2px solid #ff33cc;
    padding-bottom: 5px;
}

/* Thread titles */
struct .structItem-title,
.structItem-title a {
    color: #ff99ff;
    text-shadow: 0 0 10px #ff33cc;
}

/* Posts background */
.message-cell {
    background: linear-gradient(135deg, #3d0066, #720099);
    border-radius: 15px;
    margin-bottom: 12px;
    box-shadow: 0 0 12px #bb33ff inset;
    color: #ffe6ff;
}

/* Scrollbar styling */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #32004d;
}

::-webkit-scrollbar-thumb {
    background: #bb33ff;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
    background: #ff33cc;
}
}
